-- migration-step: function:dws.refresh_operating_sales_product_allocation(IN p_source_table regclass, IN p_target_table regclass, IN p_normalize_historical_codes boolean, IN p_brush_rule character varying, IN p_exclude_auxiliary_lines boolean)
CREATE OR REPLACE PROCEDURE dws.refresh_operating_sales_product_allocation(IN p_source_table regclass, IN p_target_table regclass, IN p_normalize_historical_codes boolean DEFAULT false, IN p_brush_rule character varying DEFAULT 'any_line_ge'::character varying, IN p_exclude_auxiliary_lines boolean DEFAULT false)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    EXECUTE FORMAT('TRUNCATE TABLE %s', p_target_table);

    EXECUTE FORMAT(
        $statement$
        INSERT INTO %1$s (
            stat_date,
            platform_code,
            platform_name,
            shop_code,
            shop_name,
            main_order_no,
            sub_order_no,
            merchant_code,
            product_spec,
            source_component_count,
            paid_component_count,
            component_index,
            merchant_code_component,
            product_mapping_id,
            large_product_category,
            product_category_l2,
            product_name,
            code_role,
            mapping_pattern,
            component_quantity,
            allocation_weight,
            source_line_gmv_amount,
            allocated_gmv_amount,
            is_mapped,
            source_id,
            source_batch_id,
            source_updated_at,
            updated_at
        )
        WITH eligible_lines AS (
            SELECT
                d.*,
                COALESCE(
                    NULLIF(BTRIM(REPLACE(d.merchant_code, '＋', '+'), E' \t\r\n'), ''),
                    'UNMAPPED'
                ) AS normalized_merchant_code,
                COALESCE(d.product_spec, '') AS normalized_product_spec
            FROM %2$s d
            WHERE d.gmv_amount > 0
              AND NOT (
                  (
                      $2 = 'main_order_sum_gt'
                      AND (
                          SELECT COALESCE(SUM(brush.order_pay_amount), 0)
                          FROM %2$s brush
                          WHERE brush.platform_code = d.platform_code
                            AND brush.shop_code = d.shop_code
                            AND brush.main_order_no = d.main_order_no
                      ) > 2000
                  )
                  OR (
                      $2 = 'any_line_ge'
                      AND EXISTS (
                          SELECT 1
                          FROM %2$s brush
                          WHERE brush.platform_code = d.platform_code
                            AND brush.shop_code = d.shop_code
                            AND brush.main_order_no = d.main_order_no
                            AND brush.order_pay_amount >= 2000
                      )
                  )
              )
              AND NOT (
                  $3
                  AND (
                      COALESCE(d.product_name, '') = 'MOCK推荐官'
                      OR COALESCE(d.product_name, '') LIKE '%%赠品勿拍%%'
                  )
              )
        ), raw_components AS (
            SELECT
                e.*,
                BTRIM(UPPER(component.component_text), E' \t\r\n') AS raw_component,
                component.component_index::SMALLINT AS component_index
            FROM eligible_lines e
            CROSS JOIN LATERAL REGEXP_SPLIT_TO_TABLE(
                e.normalized_merchant_code,
                E'\\+'
            ) WITH ORDINALITY AS component(component_text, component_index)
            WHERE NULLIF(BTRIM(component.component_text, E' \t\r\n'), '') IS NOT NULL
        ), split_components AS (
            SELECT
                r.*,
                CASE
                    WHEN $1 AND r.raw_component ~ '^[0-9]+MLXYD$'
                        THEN 'M-MLXY-XD-' || SUBSTRING(r.raw_component FROM '^([0-9]+)')
                    WHEN $1 AND r.raw_component ~ '^[0-9]+SYD$'
                        THEN 'M-NXSY-XD-' || SUBSTRING(r.raw_component FROM '^([0-9]+)')
                    WHEN $1 AND r.raw_component ~ '^[0-9]+MGD$'
                        THEN 'M-MGNT-XD-' || SUBSTRING(r.raw_component FROM '^([0-9]+)')
                    WHEN $1 AND r.raw_component ~ '^[0-9]+SY$'
                        THEN 'M-NXSY-' || SUBSTRING(r.raw_component FROM '^([0-9]+)')
                    WHEN $1 AND r.raw_component ~ '^[0-9]+MG$'
                        THEN 'M-MGNT-' || SUBSTRING(r.raw_component FROM '^([0-9]+)')
                    WHEN $1 AND r.raw_component ~ '^[0-9]+ML$'
                        THEN 'M-MLXY-' || SUBSTRING(r.raw_component FROM '^([0-9]+)')
                    ELSE r.raw_component
                END AS merchant_code_component
            FROM raw_components r
        ), counted_components AS (
            SELECT
                s.*,
                COUNT(*) OVER (
                    PARTITION BY s.platform_code, s.shop_code, s.sub_order_no
                )::SMALLINT AS source_component_count,
                POSITION('赠' IN s.normalized_product_spec) AS gift_position
            FROM split_components s
        ), component_rules AS (
            SELECT
                c.*,
                CASE
                    WHEN c.gift_position > 0 THEN
                        RTRIM(
                            REPLACE(
                                LEFT(c.normalized_product_spec, c.gift_position - 1),
                                '＋',
                                '+'
                            ),
                            E' +（(【[\t\r\n:：,，、*xX'
                        )
                    ELSE ''
                END AS paid_spec_prefix
            FROM counted_components c
        ), classified_components AS (
            SELECT
                r.*,
                CASE
                    WHEN r.gift_position > 0 THEN
                        LEAST(
                            r.source_component_count,
                            GREATEST(
                                1,
                                1
                                + LENGTH(r.paid_spec_prefix)
                                - LENGTH(REPLACE(r.paid_spec_prefix, '+', ''))
                            )
                        )::SMALLINT
                    ELSE r.source_component_count
                END AS paid_component_count
            FROM component_rules r
        ), paid_components AS (
            SELECT *
            FROM classified_components
            WHERE component_index <= paid_component_count
        ), mapped_components AS (
            SELECT
                p.*,
                m.mapping_id AS product_mapping_id,
                COALESCE(m.large_product_category, '未映射') AS large_product_category,
                COALESCE(m.product_category_l2, '未映射') AS product_category_l2,
                COALESCE(m.product_name, '未映射产品') AS mapped_product_name,
                COALESCE(m.code_role, 'unmapped') AS code_role,
                m.code_pattern AS mapping_pattern,
                CASE
                    WHEN m.match_rule = 'suffix_quantity' THEN
                        SUBSTRING(
                            p.merchant_code_component
                            FROM LENGTH(m.code_prefix) + 1
                        )::NUMERIC
                    WHEN m.match_rule = 'exact' THEN 1::NUMERIC
                    ELSE COALESCE(
                        NULLIF(
                            SUBSTRING(p.merchant_code_component FROM '-([0-9]+)$'),
                            ''
                        )::NUMERIC,
                        1::NUMERIC
                    )
                END AS component_quantity,
                m.mapping_id IS NOT NULL AS is_mapped
            FROM paid_components p
            LEFT JOIN LATERAL (
                SELECT
                    candidate.*,
                    parent.category_name AS large_product_category,
                    child.category_name AS product_category_l2,
                    product.product_name
                FROM dim.dim_company_product_code_mapping candidate
                JOIN dim.dim_influencer_product product
                  ON product.product_id = candidate.product_id
                 AND product.is_active
                JOIN dim.dim_influencer_product_category child
                  ON child.category_id = product.category_id
                 AND child.category_level = 2
                 AND child.is_active
                JOIN dim.dim_influencer_product_category parent
                  ON parent.category_id = child.parent_category_id
                 AND parent.category_level = 1
                 AND parent.is_active
                WHERE candidate.is_active
                  AND (
                      (
                          candidate.match_rule = 'exact'
                          AND UPPER(candidate.code_pattern) = p.merchant_code_component
                      )
                      OR (
                          candidate.match_rule = 'suffix_quantity'
                          AND LEFT(
                              p.merchant_code_component,
                              LENGTH(candidate.code_prefix)
                          ) = UPPER(candidate.code_prefix)
                          AND SUBSTRING(
                              p.merchant_code_component
                              FROM LENGTH(candidate.code_prefix) + 1
                          ) ~ '^[0-9]+$'
                      )
                  )
                ORDER BY
                    CASE WHEN candidate.match_rule = 'exact' THEN 0 ELSE 1 END,
                    LENGTH(candidate.code_pattern) DESC,
                    candidate.mapping_id
                LIMIT 1
            ) m ON TRUE
        ), weighted_components AS (
            SELECT
                m.*,
                SUM(m.component_quantity) OVER (
                    PARTITION BY m.platform_code, m.shop_code, m.sub_order_no
                ) AS total_component_quantity
            FROM mapped_components m
        ), rounded_components AS (
            SELECT
                w.*,
                ROUND(
                    w.component_quantity / NULLIF(w.total_component_quantity, 0),
                    10
                ) AS allocation_weight,
                ROUND(
                    w.gmv_amount * w.component_quantity
                    / NULLIF(w.total_component_quantity, 0),
                    2
                ) AS rounded_gmv_amount
            FROM weighted_components w
        ), reconciled_components AS (
            SELECT
                r.*,
                SUM(r.rounded_gmv_amount) OVER (
                    PARTITION BY r.platform_code, r.shop_code, r.sub_order_no
                ) AS rounded_gmv_total,
                ROW_NUMBER() OVER (
                    PARTITION BY r.platform_code, r.shop_code, r.sub_order_no
                    ORDER BY r.component_index DESC
                ) AS reverse_component_rank
            FROM rounded_components r
        )
        SELECT
            r.stat_date,
            r.platform_code,
            r.platform_name,
            r.shop_code,
            r.shop_name,
            r.main_order_no,
            r.sub_order_no,
            r.normalized_merchant_code,
            NULLIF(r.normalized_product_spec, ''),
            r.source_component_count,
            r.paid_component_count,
            r.component_index,
            r.merchant_code_component,
            r.product_mapping_id,
            r.large_product_category,
            r.product_category_l2,
            r.mapped_product_name,
            r.code_role,
            r.mapping_pattern,
            ROUND(r.component_quantity, 2),
            r.allocation_weight,
            r.gmv_amount,
            CASE
                WHEN r.reverse_component_rank = 1 THEN
                    ROUND(
                        r.rounded_gmv_amount
                        + r.gmv_amount
                        - r.rounded_gmv_total,
                        2
                    )
                ELSE r.rounded_gmv_amount
            END,
            r.is_mapped,
            r.source_id,
            r.source_batch_id,
            r.source_updated_at,
            NOW()
        FROM reconciled_components r
        $statement$,
        p_target_table,
        p_source_table
    )
    USING
        p_normalize_historical_codes,
        p_brush_rule,
        p_exclude_auxiliary_lines;
END;
$procedure$

-- migration-step: view:common.v_ingest_batch_shop_context
CREATE OR REPLACE VIEW "common"."v_ingest_batch_shop_context" AS
 SELECT log.batch_id,
    log.platform_code,
    log.platform_name,
    log.shop_code,
    log.shop_name,
    log.shop_identity_key,
    dim.company_code,
    dim.company_name,
    log.data_domain,
    log.target_table,
    log.source_file_name,
    log.shop_mapping_status,
    log.shop_mapping_source,
    log.ingest_status,
    log.updated_at
   FROM ods.ods_file_ingest_log log
     LEFT JOIN dim.dim_platform_shop_company dim ON dim.shop_identity_key::text = log.shop_identity_key::text AND dim.is_active AND dim.valid_to IS NULL;;

-- migration-step: view:dwd.v_statement_split_detail
CREATE OR REPLACE VIEW "dwd"."v_statement_split_detail" AS
 SELECT split.id AS split_id,
    split.ods_id,
    split.batch_id,
    split.split_index,
    ods.transaction_date,
    ods.transaction_time,
    ods.transaction_type,
    COALESCE(NULLIF(split.remark::text, ''::text), ods.summary) AS summary,
    ods.debit_amount,
    ods.credit_amount,
    ods.balance,
    ods.transaction_no,
    split.split_amount,
    split.original_amount,
    split.adjusted_diff,
    split.original_amount + split.adjusted_diff AS adjusted_amount,
    split.is_adjusted,
    split.expense_type_id,
    expense.name AS expense_type_name,
    split.account_entry_id,
    account.name AS account_entry_name,
    split.remark,
    split.updated_at,
    ods.account_name,
    ods.summary AS source_summary
   FROM dwd.dwd_statement_split split
     JOIN ods.ods_bank_statement ods ON ods.id = split.ods_id
     LEFT JOIN dim.dim_expense_type expense ON expense.id = split.expense_type_id
     LEFT JOIN dim.dim_account_entry account ON account.id = split.account_entry_id;;

